import os
import json
import time
from typing import List, Dict, Any
from datetime import datetime, timedelta
from flask import Flask, request, jsonify, send_from_directory, Response
from flask_cors import CORS
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa

app = Flask(__name__, static_folder='.')
CORS(app)

class ResearchEngine:
    def __init__(self):
        self.cerebras_key = os.environ.get("CEREBRAS_API_KEY")
        self.exa_key = os.environ.get("EXA_API_KEY")

        if not self.cerebras_key:
            raise ValueError("CEREBRAS_API_KEY not found in environment")
        if not self.exa_key:
            raise ValueError("EXA_API_KEY not found in environment")

        self.cerebras_client = Cerebras(api_key=self.cerebras_key)
        self.exa_client = Exa(api_key=self.exa_key)
        self.model_id = "qwen-3-235b-a22b-instruct-2507"
        self.max_tokens = 20000

    def analyze_query(self, query: str) -> Dict[str, Any]:
        system_prompt = "Elemezd a kérdést és határozd meg: complexity (1-10), research_depth (shallow/medium/deep/exhaustive), source_types (academic/news/general/technical/mixed), temporal_relevance (recent/current_year/last_year/historical/all_time), query_count (10-50), iterative_refinement (true/false). Válaszolj JSON-ban."

        try:
            response = self.cerebras_client.chat.completions.create(
                model=self.model_id,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": f"Elemezd: {query}"}
                ],
                max_tokens=20000,
                temperature=0.3,
                response_format={"type": "json_object"}
            )

            analysis = json.loads(response.choices[0].message.content)
            return analysis

        except Exception as e:
            return {
                "complexity": 7,
                "research_depth": "deep",
                "source_types": "mixed",
                "temporal_relevance": "all_time",
                "query_count": 20,
                "iterative_refinement": False
            }

    def generate_queries(self, user_query: str, analysis: Dict[str, Any]) -> List[Dict[str, Any]]:
        query_count = analysis.get("query_count", 20)

        system_prompt = f"Generálj pontosan {query_count} különböző keresési lekérdezést. Minden query-hez adj meg: query (szöveg), type (neural/keyword/auto), category (company/research paper/news/tweet/github/pdf ha releváns), priority (1-10). Válaszolj JSON formátumban egy queries listával."

        user_message = f"Kérdés: {user_query}\n\nElemzés: {json.dumps(analysis)}\n\nGenerálj {query_count} query-t."

        try:
            response = self.cerebras_client.chat.completions.create(
                model=self.model_id,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_message}
                ],
                max_tokens=20000,
                temperature=0.8,
                response_format={"type": "json_object"}
            )

            content = json.loads(response.choices[0].message.content)
            queries = content.get("queries", [])

            if len(queries) < query_count:
                response2 = self.cerebras_client.chat.completions.create(
                    model=self.model_id,
                    messages=[
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": f"Generálj {query_count - len(queries)} ÚJABB query-t: {user_query}"}
                    ],
                    max_tokens=20000,
                    temperature=0.9,
                    response_format={"type": "json_object"}
                )
                extra = json.loads(response2.choices[0].message.content).get("queries", [])
                queries.extend(extra)

            return queries[:query_count]

        except Exception as e:
            return [{"query": user_query, "type": "auto", "category": None, "priority": 10} for _ in range(query_count)]

    def search_exa(self, queries: List[Dict[str, Any]], analysis: Dict[str, Any]) -> List[Dict[str, Any]]:
        all_results = []
        seen_urls = set()

        end_date = datetime.now()
        temporal = analysis.get("temporal_relevance", "all_time")

        if temporal == "recent":
            start_date = end_date - timedelta(days=30)
        elif temporal == "current_year":
            start_date = datetime(end_date.year, 1, 1)
        elif temporal == "last_year":
            start_date = end_date - timedelta(days=365)
        else:
            start_date = end_date - timedelta(days=1825)

        sorted_queries = sorted(queries, key=lambda x: x.get("priority", 5), reverse=True)

        for query_obj in sorted_queries:
            query_text = query_obj.get("query", "")
            search_type = query_obj.get("type", "auto")
            category = query_obj.get("category")
            priority = query_obj.get("priority", 5)

            try:
                search_params = {
                    "query": query_text,
                    "type": search_type,
                    "num_results": 100,
                    "use_autoprompt": True,
                    "start_published_date": start_date.strftime("%Y-%m-%d"),
                    "end_published_date": end_date.strftime("%Y-%m-%d"),
                    "start_crawl_date": start_date.strftime("%Y-%m-%d"),
                    "end_crawl_date": end_date.strftime("%Y-%m-%d"),
                    "livecrawl": "fallback",
                    "text": {
                        "max_characters": 15000,
                        "include_html_tags": True
                    },
                    "highlights": {
                        "num_sentences": 15,
                        "highlights_per_url": 8,
                        "query": query_text
                    },
                    "summary": True,
                    "subpages": 3,
                    "subpage_target": {"mode": "auto"}
                }

                if category:
                    search_params["category"] = category

                search_response = self.exa_client.search_and_contents(**search_params)

                for result in search_response.results:
                    if result.url in seen_urls:
                        continue

                    seen_urls.add(result.url)

                    result_data = {
                        "id": result.id,
                        "title": result.title,
                        "url": result.url,
                        "text": result.text if result.text else "",
                        "highlights": result.highlights if hasattr(result, "highlights") else [],
                        "summary": result.summary if hasattr(result, "summary") else "",
                        "author": getattr(result, "author", ""),
                        "published_date": getattr(result, "published_date", ""),
                        "score": getattr(result, "score", 0),
                        "query_source": query_text,
                        "priority": priority
                    }

                    all_results.append(result_data)

            except Exception as e:
                continue

        return all_results

    def rank_results(self, results: List[Dict[str, Any]], top_n: int = 300) -> List[Dict[str, Any]]:
        for result in results:
            score = 0
            score += result.get("score", 0) * 10
            score += result.get("priority", 5) * 2
            score += len(result.get("highlights", [])) * 3
            score += (10 if result.get("summary") else 0)
            score += (5 if result.get("author") else 0)
            score += len(result.get("text", "")) / 1000
            result["final_score"] = score

        sorted_results = sorted(results, key=lambda x: x.get("final_score", 0), reverse=True)
        return sorted_results[:top_n]

    def build_context(self, results: List[Dict[str, Any]]) -> str:
        parts = []
        parts.append("FORRÁSOK ÉS TARTALOM")
        parts.append("=" * 100)

        for idx, result in enumerate(results, 1):
            section = []
            section.append(f"FORRÁS #{idx}")
            section.append(f"Cím: {result.get('title', 'N/A')}")
            section.append(f"URL: {result.get('url', 'N/A')}")
            section.append(f"ID: {result.get('id', 'N/A')}")
            section.append(f"Szerző: {result.get('author', 'N/A')}")
            section.append(f"Dátum: {result.get('published_date', 'N/A')}")
            section.append(f"Pontszám: {result.get('final_score', 0):.2f}")

            if result.get("summary"):
                section.append(f"Összefoglaló: {result['summary']}")

            if result.get("highlights"):
                section.append("Kiemelések:")
                for h in result["highlights"]:
                    section.append(f"  - {h}")

            if result.get("text"):
                text = result["text"]
                if len(text) > 12000:
                    text = text[:12000] + "..."
                section.append(f"Tartalom: {text}")

            section.append("-" * 100)
            parts.extend(section)

        return "\n".join(parts)

    def generate_answer(self, query: str, context: str, analysis: Dict[str, Any]) -> str:
        system_prompt = "Te egy fejlett AI kutató vagy, aki magyar nyelven válaszol. Írj rendkívül részletes, átfogó választ (50000+ karakter). Használj markdown fejléceket. Minden állítást támassz alá [Forrás: URL] hivatkozással. Technikai részletek, számok, dátumok pontosan. Történeti háttér, jelenlegi helyzet, jövőbeli kilátások. Ne ismételj, ne összegezz. Minden bekezdés új információt adjon."

        user_message = f"Kérdés: {query}\n\nElemzés: {json.dumps(analysis, ensure_ascii=False)}\n\nForrások:\n{context}\n\nÍrj extrém részletes választ magyarul, legalább 50000 karakter."

        try:
            response = self.cerebras_client.chat.completions.create(
                model=self.model_id,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_message}
                ],
                max_tokens=20000,
                temperature=0.7
            )

            return response.choices[0].message.content

        except Exception as e:
            return f"Hiba a válasz generálása során: {str(e)}"

    def generate_answer_stream(self, query: str, context: str, analysis: Dict[str, Any]):
        system_prompt = "Te egy fejlett AI kutató vagy, aki magyar nyelven válaszol. Írj rendkívül részletes, átfogó választ (50000+ karakter). Használj markdown fejléceket. Minden állítást támassz alá [Forrás: URL] hivatkozással. Technikai részletek, számok, dátumok pontosan. Történeti háttér, jelenlegi helyzet, jövőbeli kilátások. Ne ismételj, ne összegezz. Minden bekezdés új információt adjon."

        user_message = f"Kérdés: {query}\n\nElemzés: {json.dumps(analysis, ensure_ascii=False)}\n\nForrások:\n{context}\n\nÍrj extrém részletes választ magyarul, legalább 50000 karakter."

        try:
            stream = self.cerebras_client.chat.completions.create(
                model=self.model_id,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_message}
                ],
                max_tokens=20000,
                temperature=0.7,
                stream=True
            )

            for chunk in stream:
                if chunk.choices[0].delta.content:
                    yield chunk.choices[0].delta.content

        except Exception as e:
            yield f"Hiba: {str(e)}"

research_engine = ResearchEngine()

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/<path:path>')
def serve_static(path):
    return send_from_directory('.', path)

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({
        "status": "ok",
        "model": research_engine.model_id,
        "max_tokens": research_engine.max_tokens
    })

@app.route('/api/research', methods=['POST'])
def research():
    try:
        data = request.json
        query = data.get('query', '')

        if not query:
            return jsonify({"error": "Query parameter is required"}), 400

        analysis = research_engine.analyze_query(query)

        queries = research_engine.generate_queries(query, analysis)

        search_results = research_engine.search_exa(queries, analysis)

        ranked_results = research_engine.rank_results(search_results, top_n=300)

        context = research_engine.build_context(ranked_results)

        if len(context) > 1500000:
            context = context[:1500000]

        answer = research_engine.generate_answer(query, context, analysis)

        return jsonify({
            "query": query,
            "answer": answer,
            "analysis": analysis,
            "sources_count": len(ranked_results),
            "queries_used": len(queries)
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/research/stream', methods=['POST'])
def research_stream():
    try:
        data = request.json
        query = data.get('query', '')

        if not query:
            return jsonify({"error": "Query parameter is required"}), 400

        def generate():
            try:
                yield f"data: {json.dumps({'type': 'status', 'message': 'Analyzing query...'})}\n\n"

                analysis = research_engine.analyze_query(query)
                yield f"data: {json.dumps({'type': 'analysis', 'data': analysis})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Generating search queries...'})}\n\n"
                queries = research_engine.generate_queries(query, analysis)
                yield f"data: {json.dumps({'type': 'queries', 'count': len(queries)})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Searching Exa AI...'})}\n\n"
                search_results = research_engine.search_exa(queries, analysis)
                yield f"data: {json.dumps({'type': 'search_results', 'count': len(search_results)})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Ranking results...'})}\n\n"
                ranked_results = research_engine.rank_results(search_results, top_n=300)
                yield f"data: {json.dumps({'type': 'ranked_results', 'count': len(ranked_results)})}\n\n"

                yield f"data: {json.dumps({'type': 'status', 'message': 'Building context...'})}\n\n"
                context = research_engine.build_context(ranked_results)

                if len(context) > 1500000:
                    context = context[:1500000]

                yield f"data: {json.dumps({'type': 'status', 'message': 'Generating answer...'})}\n\n"

                for chunk in research_engine.generate_answer_stream(query, context, analysis):
                    yield f"data: {json.dumps({'type': 'answer_chunk', 'content': chunk})}\n\n"

                yield f"data: {json.dumps({'type': 'done'})}\n\n"

            except Exception as e:
                yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}\n\n"

        return Response(generate(), mimetype='text/event-stream')

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/analyze', methods=['POST'])
def analyze():
    try:
        data = request.json
        query = data.get('query', '')

        if not query:
            return jsonify({"error": "Query parameter is required"}), 400

        analysis = research_engine.analyze_query(query)

        return jsonify({
            "query": query,
            "analysis": analysis
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/generate-queries', methods=['POST'])
def generate_queries_endpoint():
    try:
        data = request.json
        query = data.get('query', '')
        analysis = data.get('analysis', {})

        if not query:
            return jsonify({"error": "Query parameter is required"}), 400

        if not analysis:
            analysis = research_engine.analyze_query(query)

        queries = research_engine.generate_queries(query, analysis)

        return jsonify({
            "query": query,
            "queries": queries,
            "count": len(queries)
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/search', methods=['POST'])
def search():
    try:
        data = request.json
        queries = data.get('queries', [])
        analysis = data.get('analysis', {})

        if not queries:
            return jsonify({"error": "Queries parameter is required"}), 400

        search_results = research_engine.search_exa(queries, analysis)

        ranked_results = research_engine.rank_results(search_results, top_n=300)

        return jsonify({
            "results": ranked_results,
            "count": len(ranked_results)
        })

    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 5000))
    app.run(host='0.0.0.0', port=port, debug=False, threaded=True)
